public partial class Studio {
 StackPanel unifiedFraming;ComboBox unifiedLayout,unifiedFit;CheckBox unifiedMirror;
 Dictionary<Slider,Func<EditSettings,double>> framingReaders=new Dictionary<Slider,Func<EditSettings,double>>();
 EditSettings DefaultFraming(){return new EditSettings{Fit=1,X=50,Y=50,Font=54,TextY=80,Volume=100};}
 EditSettings CopySettings(EditSettings s){return new JavaScriptSerializer().Deserialize<EditSettings>(new JavaScriptSerializer().Serialize(s));}
 void BuildUnifiedFraming(){
  unifiedFraming=new StackPanel{Margin=new Thickness(0,8,0,8)};var expander=new Expander{Header="Кадрирование, вебкамера и цвет",Content=unifiedFraming,Margin=new Thickness(0,12,0,10)};montageInspector.Children.Add(expander);
  unifiedFraming.Children.Add(MT("Настройки выбранного видео или изображения"));
  unifiedLayout=MCombo(new[]{"Обычный кадр","Игра + камера сверху","Игра + камера снизу"},0,delegate{EditUnifiedFraming(s=>s.Layout=unifiedLayout.SelectedIndex);});unifiedFraming.Children.Add(unifiedLayout);
  unifiedFit=MCombo(new[]{"Заполнить / обрезать","Вписать с полями"},1,delegate{EditUnifiedFraming(s=>s.Fit=unifiedFit.SelectedIndex);});unifiedFraming.Children.Add(unifiedFit);
  FramingSlider("Смещение видео X",0,100,s=>s.X,(s,v)=>s.X=v);FramingSlider("Смещение видео Y",0,100,s=>s.Y,(s,v)=>s.Y=v);
  FramingSlider("Камера: положение X",0,100,s=>s.CamX,(s,v)=>s.CamX=v);FramingSlider("Камера: положение Y",0,100,s=>s.CamY,(s,v)=>s.CamY=v);
  FramingSlider("Камера: ширина, % исходника",5,100,s=>s.CamW,(s,v)=>s.CamW=v);FramingSlider("Камера: высота, % исходника",5,100,s=>s.CamH,(s,v)=>s.CamH=v);FramingSlider("Доля камеры в готовом кадре",15,50,s=>s.CamPanel,(s,v)=>s.CamPanel=v);
  FramingSlider("Яркость",-.3,.3,s=>s.Brightness,(s,v)=>s.Brightness=v);FramingSlider("Контраст",.5,1.5,s=>s.Contrast,(s,v)=>s.Contrast=v);FramingSlider("Насыщенность",0,2,s=>s.Saturation,(s,v)=>s.Saturation=v);
  unifiedMirror=new CheckBox{Content="Отразить видео",Margin=new Thickness(0,6,0,8)};unifiedMirror.Checked+=delegate{EditUnifiedFraming(s=>s.Mirror=true);};unifiedMirror.Unchecked+=delegate{EditUnifiedFraming(s=>s.Mirror=false);};unifiedFraming.Children.Add(unifiedMirror);
  unifiedFraming.Children.Add(MB("Добавить SRT / ASS к клипу",delegate{if(!CanEditMontage())return;var d=new OpenFileDialog{Filter="Субтитры|*.srt;*.ass"};if(d.ShowDialog(window)==true)EditUnifiedFraming(s=>s.Subtitles=d.FileName);}));
  unifiedFraming.Children.Add(MB("Убрать субтитры",delegate{EditUnifiedFraming(s=>s.Subtitles=null);}));unifiedFraming.Children.Add(MB("Сбросить кадрирование и цвет",delegate{if(!CanEditMontage())return;SelectedMontage().Framing=null;FillMontageInspector();MontageChanged();}));
 }
 void FramingSlider(string label,double min,double max,Func<EditSettings,double> read,Action<EditSettings,double> write){var title=MT(label);var slider=new Slider{Minimum=min,Maximum=max,Value=Math.Max(min,Math.Min(max,read(DefaultFraming()))),Margin=new Thickness(0,0,0,8)};framingReaders.Add(slider,read);slider.ValueChanged+=delegate{title.Text=label+" • "+slider.Value.ToString("0.##");EditUnifiedFraming(s=>write(s,slider.Value));};unifiedFraming.Children.Add(title);unifiedFraming.Children.Add(slider);}
 void EditUnifiedFraming(Action<EditSettings> edit){if(montageUpdating||!CanEditMontage()||TrackOf(SelectedMontage()).Kind!="video")return;var c=SelectedMontage();if(c.Framing==null)c.Framing=DefaultFraming();edit(c.Framing);MontageChanged();}
 void FillUnifiedFraming(){if(unifiedFraming==null)return;var c=SelectedMontage();bool editable=c!=null&&TrackOf(c)!=null&&TrackOf(c).Kind=="video"&&!TrackOf(c).Locked;unifiedFraming.IsEnabled=editable;var s=c==null||c.Framing==null?DefaultFraming():c.Framing;unifiedLayout.SelectedIndex=s.Layout;unifiedFit.SelectedIndex=s.Fit;unifiedMirror.IsChecked=s.Mirror;unifiedMirror.IsEnabled=editable;foreach(var p in framingReaders){p.Key.IsEnabled=editable;p.Key.Value=p.Value(s);}}
 void ValidateFraming(EditSettings s,bool files){if(s==null)return;double[] values={s.X,s.Y,s.CamX,s.CamY,s.CamW,s.CamH,s.CamPanel,s.Font,s.TextY,s.Brightness,s.Contrast,s.Saturation};if(values.Any(v=>!Finite(v))||s.Layout<0||s.Layout>2||s.Fit<0||s.Fit>1||s.X<0||s.X>100||s.Y<0||s.Y>100||s.CamX<0||s.CamX>100||s.CamY<0||s.CamY>100||s.CamW<5||s.CamW>100||s.CamH<5||s.CamH>100||s.CamPanel<15||s.CamPanel>50||s.Font<8||s.Font>200||s.TextY<0||s.TextY>100||s.Brightness<-.3||s.Brightness>.3||s.Contrast<.5||s.Contrast>1.5||s.Saturation<0||s.Saturation>2||(s.Caption??"").Length>10000)throw new Exception("Некорректные параметры кадрирования.");if(!String.IsNullOrEmpty(s.Subtitles)){string ext=Path.GetExtension(s.Subtitles).ToLowerInvariant();if(ext!=".srt"&&ext!=".ass")throw new Exception("Поддерживаются SRT и ASS.");if(files&&!File.Exists(s.Subtitles))throw new Exception("Файл субтитров не найден.");}}
 string UnifiedFramingFilter(MontageClip c,int w,int h,double offset,string job){if(c.Framing==null)return "";var s=CopySettings(c.Framing);s.Speed=1;File.WriteAllText(Path.Combine(job,"title-"+c.Id+".txt"),Wrap(s.Caption??"",Math.Max(6,(int)(1080/(s.Font*.59))-2)),new System.Text.UTF8Encoding(false));string subname="subs"+Path.GetExtension(s.Subtitles??"").ToLowerInvariant();if(!String.IsNullOrEmpty(s.Subtitles))File.Copy(s.Subtitles,Path.Combine(job,"subs-"+c.Id+Path.GetExtension(s.Subtitles).ToLowerInvariant()),true);return Filter(s,w,h,offset,"u"+c.Id).Replace("textfile=title.txt","textfile=title-"+c.Id+".txt").Replace("filename="+subname,"filename=subs-"+c.Id+Path.GetExtension(s.Subtitles??"").ToLowerInvariant())+",";}
 async Task<MontageAsset> ReadUnifiedAsset(string path,bool audio){var r=await Run(ffmpeg,"-hide_banner -i "+Q(path),root,null,null);var match=Regex.Match(r.Error,@"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)");var dims=Regex.Match(r.Error.Split('\n').FirstOrDefault(l=>l.Contains("Video:"))??"",@"\b(\d{2,5})x(\d{2,5})\b");if(!match.Success||(!audio&&!dims.Success))throw new Exception("Не удалось открыть исходник проекта.");double len=double.Parse(match.Groups[1].Value)*3600+double.Parse(match.Groups[2].Value)*60+double.Parse(match.Groups[3].Value,CultureInfo.InvariantCulture);return new MontageAsset{Id=Id(),Path=Path.GetFullPath(path),Kind=audio?"audio":"video",Duration=len,Audio=r.Error.Contains("Audio:"),Width=dims.Success?int.Parse(dims.Groups[1].Value):0,Height=dims.Success?int.Parse(dims.Groups[2].Value):0};}
 async Task ImportLegacyProject(Project p){
  if(!File.Exists(p.Source)){var d=new OpenFileDialog{Title="Найдите исходник проекта",CheckFileExists=true};if(d.ShowDialog(window)!=true)return;p.Source=d.FileName;}
  var settings=CopySettings(p.Settings);string legacyCaption=settings.Caption;settings.Caption=null;settings.Music=Relink(settings.Music,"Найдите музыку проекта","Аудио|*.mp3;*.wav;*.m4a;*.flac;*.ogg|Все файлы|*.*");settings.Subtitles=Relink(settings.Subtitles,"Найдите субтитры проекта","Субтитры|*.srt;*.ass");ValidateFraming(settings,true);
  var doc=new MontageDocument{Aspect=settings.Aspect,Resolution=settings.Resolution,Fps=settings.Fps};var video=await ReadUnifiedAsset(p.Source,false);doc.Assets.Add(video);var t=new MontageTrack{Id=Id(),Kind="video",Name="Видео"};doc.Tracks.Add(t);double at=0;var ranges=p.Clips.Count>0?p.Clips:new List<Clip>{new Clip{Start=p.In,End=p.Out}};
  foreach(var c in ranges){doc.Items.Add(new MontageClip{Id=Id(),Track=t.Id,Asset=video.Id,Start=at,In=c.Start,Length=(c.End-c.Start)/settings.Speed,Speed=settings.Speed,Volume=settings.Volume,Framing=CopySettings(settings)});at+=(c.End-c.Start)/settings.Speed;}
  if(!String.IsNullOrEmpty(legacyCaption)){var textTrack=new MontageTrack{Id=Id(),Kind="text",Name="Текст"};doc.Tracks.Insert(0,textTrack);doc.Items.Add(new MontageClip{Id=Id(),Track=textTrack.Id,Start=0,Length=at,Text=Wrap(legacyCaption,Math.Max(6,(int)(1080/(settings.Font*.59))-2)),Font=settings.Font,Y=settings.TextY,Style=settings.Style==1?2:settings.Style==2?4:0});}
  if(!String.IsNullOrEmpty(settings.Music)){var a=await ReadUnifiedAsset(settings.Music,true);doc.Assets.Add(a);var track=new MontageTrack{Id=Id(),Kind="audio",Name="Музыка"};doc.Tracks.Insert(0,track);doc.Items.Add(new MontageClip{Id=Id(),Track=track.Id,Asset=a.Id,Length=at,Volume=settings.MusicVolume,Loop=true,Fade=settings.MusicFade?Math.Min(1,at/2):0});}
  await LoadMontage(doc);Status("Проект открыт в едином редакторе. Сохраните его, чтобы продолжить монтаж на дорожках.");
 }
 async Task TestUnifiedEditor(List<string> report){
  unifiedTest=true;try{var container=(Panel)Btn("NavEditor").Parent;if(container.Children.OfType<Button>().Any(b=>Convert.ToString(b.Content)=="Дорожки"))throw new Exception("Duplicate editor navigation remains");Page(false);Btn("NavEditor").RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));if(!montageMode||montagePage.Visibility!=Visibility.Visible||UI<Grid>("EditorPage").Visibility==Visibility.Visible)throw new Exception("Editor navigation opened the legacy workspace");var existing=montage;Page(false);Page(true);if(!Object.ReferenceEquals(existing,montage))throw new Exception("Switching to downloads replaced the project");
   var legacy=new Project{Version=3,Source=Path.Combine(root,"test-track-blue.mp4"),In=0,Out=2,Clips=new List<Clip>{new Clip{Start=0,End=1},new Clip{Start=2,End=3}},Settings=new EditSettings{Font=54,Volume=70,Aspect=0,Resolution=1,Layout=1,Caption="Единый редактор",Music=Path.Combine(root,"test-track-tone.wav"),MusicVolume=35,TextY=80,Fit=0,X=50,Y=50}};
   await ImportLegacyProject(legacy);if(montage.Items.Count!=4||montage.Items[0].Framing.Layout!=1||!montage.Items.Any(c=>c.Loop)||montage.Duration!=2)throw new Exception("Legacy project was not migrated completely");string output=Path.Combine(root,"test-unified.mp4");var rendered=await RenderMontage(montage,output,true,false,0,2,null,null);if(rendered.Code!=0)throw new Exception(rendered.Error);var probe=await Run(ffmpeg,"-hide_banner -i "+Q(output),root,null,null);if(!probe.Error.Contains("270x480")||!probe.Error.Contains("Audio:"))throw new Exception("Unified framing/music export metadata failed");
   SelectMontage(montage.Items.First(c=>TrackOf(c).Kind=="video"));montageSeek.Value=.5;string frame=Path.Combine(root,"test-unified.png");var shown=await RenderMontage(montage,frame,true,true,.5,.1,null,null);if(shown.Code!=0)throw new Exception(shown.Error);await LoadMontage(existing);montageSeek.Value=1.5;SelectMontage(montage.Items.First(c=>TrackOf(c).Kind=="video"));var designed=await RenderMontage(montage,frame,true,true,1.5,.1,null,null);if(designed.Code!=0)throw new Exception(designed.Error);montageImage.Source=ReadBitmap(frame);multiTimeline.Fit();window.UpdateLayout();await window.Dispatcher.InvokeAsync(delegate{},System.Windows.Threading.DispatcherPriority.ContextIdle);if(!montagePage.IsVisible||UI<Grid>("DownloadPage").IsVisible)throw new Exception("Shared editor visibility failed after layout");Screenshot("studio-unified.png");Page(false);await window.Dispatcher.InvokeAsync(delegate{},System.Windows.Threading.DispatcherPriority.ContextIdle);Screenshot("studio-home.png");ShowMontage();report.Add("PASS one editor tab, shared workspace navigation, legacy project migration with framing/titles/looped music and real unified export");
  }finally{unifiedTest=false;}
 }
}
